def sequential_search(arr, element):
    """
    Search for `element` in `arr` sequentially.

    Returns:
        tuple: (found, index) where `found` is True if the element exists
               in the array, and `index` is its position (or -1 if not found).
    """
    for index, value in enumerate(arr):
        if value == element:
            return (True, index)
    return (False, -1)


if __name__ == "__main__":
    assert sequential_search([11, 23, 58, 31, 56, 77, 43, 12, 65, 19], 31) == (True, 3)
    assert sequential_search([12, 32, 45, 62, 35, 47, 44, 61], 61) == (True, 7)
    assert sequential_search([9, 10, 17, 19, 22, 39, 48, 56], 48) == (True, 6)
    assert sequential_search([1, 2, 3], 4) == (False, -1)
    assert sequential_search([], 1) == (False, -1)
    print("All tests passed!")
