def start_withp(words):
    """
    Return a tuple of the first two words (across all strings in the list)
    that start with the letter 'p' (case-insensitive).
    Returns None if fewer than two such words are found.
    """
    found = []
    for phrase in words:
        for word in phrase.split():
            if word[0].lower() == 'p':
                found.append(word)
                if len(found) == 2:
                    return tuple(found)
    return None


