def magic_square_test(my_matrix):
    n = len(my_matrix)
    if n == 0:
        return False
    # Ensure the matrix is square
    for row in my_matrix:
        if len(row) != n:
            return False

    target = sum(my_matrix[0])

    # Check row sums
    for row in my_matrix:
        if sum(row) != target:
            return False

    # Check column sums
    for col in range(n):
        if sum(my_matrix[row][col] for row in range(n)) != target:
            return False

    # Check main diagonal
    if sum(my_matrix[i][i] for i in range(n)) != target:
        return False

    # Check anti-diagonal
    if sum(my_matrix[i][n - 1 - i] for i in range(n)) != target:
        return False

    return True


