def _sum_proper_divisors(n):
    """Return the sum of proper divisors of n (divisors excluding n itself)."""
    if n < 2:
        return 0
    total = 1
    i = 2
    while i * i <= n:
        if n % i == 0:
            total += i
            other = n // i
            if other != i:
                total += other
        i += 1
    return total


def amicable_numbers_sum(limit):
    """Sum all amicable numbers from 1 to limit (inclusive)."""
    if not isinstance(limit, int):
        raise TypeError("Input must be an integer.")
    if limit < 1:
        return 0

    # Sieve of proper-divisor sums for numbers up to limit
    div_sum = [0] * (limit + 1)
    for i in range(1, limit // 2 + 1):
        for j in range(2 * i, limit + 1, i):
            div_sum[j] += i

    total = 0
    for a in range(2, limit + 1):
        b = div_sum[a]
        if b == a:
            continue  # perfect number, not amicable
        # Partner may lie outside the sieve range
        b_sum = div_sum[b] if b <= limit else _sum_proper_divisors(b)
        if b_sum == a:
            total += a
    return total


if __name__ == "__main__":
    assert amicable_numbers_sum(999) == 504
    assert amicable_numbers_sum(9999) == 31626
    assert amicable_numbers_sum(99) == 0
    print("All tests passed.")
