The function uses memoized recursion. Each call compares `n` with the sum of the results for `n/2`, `n/3`, `n/4` and `n/5`, where each division is integer division. The base case is `f(0) = 0`, and the cache means no value is computed twice.

```python
from functools import lru_cache


def get_max_sum(n):
    """
    Compute f(n) = max(f(n//2) + f(n//3) + f(n//4) + f(n//5), n)
    using memoized recursion.
    """
    @lru_cache(maxsize=None)
    def f(x):
        if x == 0:
            return 0
        return max(f(x // 2) + f(x // 3) + f(x // 4) + f(x // 5), x)

    return f(n)


if __name__ == "__main__":
    assert get_max_sum(60) == 106
    assert get_max_sum(10) == 12
    assert get_max_sum(2) == 2
    print("All tests passed!")
