def magic_square_test(my_matrix):
    n = len(my_matrix)
    if n == 0 or any(len(row) != n for row in my_matrix):
        return False

    target = sum(my_matrix[0])

    # Check rows
    for row in my_matrix:
        if sum(row) != target:
            return False

    # Check columns
    for col in range(n):
        if sum(my_matrix[row][col] for row in range(n)) != target:
            return False

    # Check main diagonal
    if sum(my_matrix[i][i] for i in range(n)) != target:
        return False

