def is_samepatterns(colors, patterns):
    """
    Return True if `colors` follows the same sequence as `patterns`,
    i.e. there is a one-to-one correspondence between pattern symbols
    and color values, applied position by position.
    """
    if len(colors) != len(patterns):
        return False

    pattern_to_color = {}
    color_to_pattern = {}

    for color, pattern in zip(colors, patterns):
        # Check the pattern -> color mapping is consistent
        if pattern in pattern_to_color:
            if pattern_to_color[pattern] != color:
                return False
        else:
            pattern_to_color[pattern] = color

        # Check the color -> pattern mapping is consistent (bijection)
        if color in color_to_pattern:
            if color_to_pattern[color] != pattern:
                return False
        else:
            color_to_pattern[color] = pattern

    return True


