The function uses memoized recursion with integer division (`n // 2`, `n // 3`, and so on). Each value is computed once, so large inputs stay fast. Small values return `n`: below 12 the sum of the parts never exceeds `n`, and `f(0) = 0` ends the recursion.

```python
from functools import lru_cache


def get_max_sum(n: int) -> int:
    """
    Return the maximum sum obtainable using:
        f(n) = max(f(n//2) + f(n//3) + f(n//4) + f(n//5), n)
    """

    @lru_cache(maxsize=None)
    def f(x: int) -> int:
        if x <= 1:
            return x
        split_sum = f(x // 2) + f(x // 3) + f(x // 4) + f(x // 5)
        return max(split_sum, x)

    return f(n)


if __name__ == "__main__":
    assert get_max_sum(60) == 106
    assert get_max_sum(10) == 12
    assert get_max_sum(2) == 2
    print(get_max_sum(60))  # 106
```

