When the same key appears in more than one dictionary, this version keeps the value from the **earliest** dictionary. The first dictionary wins, then the second, then the third. This matches the behavior of `collections.ChainMap`. If you want later values to override earlier ones instead, use `{**dict1, **dict2, **dict3}`.

```python
import collections


def merge_dictionaries_three(dict1, dict2, dict3):
    """
    Merge three dictionaries into a single dictionary.
    If a key appears in more than one dictionary, the value from the
    earliest dictionary (dict1, then dict2, then dict3) is kept.
    """
    return dict(collections.ChainMap({}, dict1, dict2, dict3))


if __name__ == "__main__":
    assert merge_dictionaries_three(
        {"R": "Red", "B": "Black", "P": "Pink"},
        {"G": "Green", "W": "White"},
        {"O": "Orange", "W": "White", "B": "Black"},
    ) == {'B': 'Black', 'R': 'Red', 'P': 'Pink', 'G': 'Green', 'W': 'White', 'O': 'Orange'}

    assert merge_dictionaries_three(
        {"R": "Red", "B": "Black", "P": "Pink"},
        {"G": "Green", "W": "White"},
        {"L": "lavender", "B": "Blue"},
    ) == {'W': 'White', 'P': 'Pink', 'B': 'Black', 'R': 'Red', 'G': 'Green', 'L': 'lavender'}

    assert merge_dictionaries_three(
        {"R": "Red", "B": "Black", "P": "Pink"},
        {"L": "lavender", "B": "Blue"},
        {"G": "Green", "W": "White"},
    ) == {'B': 'Black', 'P': 'Pink', 'R': 'Red', 'G': 'Green', 'L': 'lavender', 'W': 'White'}

    print("All tests passed!")
```

