def replace_spaces(text):
    """
    Replace whitespace characters with underscores and underscores with spaces.
    """
    result = []
    for ch in text:
        if ch.isspace():
            result.append('_')
        elif ch == '_':
            result.append(' ')
        else:
            result.append(ch)
    return ''.join(result)


if __name__ == "__main__":
