```python
def filter_data(students, h, w):
    """
    Filter students whose height and weight are both at least the given minimums.

    :param students: dict mapping student name -> (height, weight)
    :param h: minimal height
    :param w: minimal weight
    :return: dict of students meeting both requirements
    """
    return {name: (height, weight)
            for name, (height, weight) in students.items()
            if height >= h and weight >= w}


if __name__ == "__main__":
