def sum_of_digits(nums):
    """
    Compute the total sum of the digits of every number in the given list.
    Nested lists/tuples are flattened, negative signs and non-digit
    characters (including non-numeric items) are ignored.
    """
    def flatten(items):
        for item in items:
            if isinstance(item, (list, tuple)):
                yield from flatten(item)
            else:
                yield item

    return sum(int(ch) for n in flatten(nums) for ch in str(n) if ch.isdigit())


