The function adds every number `a` from 2 up to the limit that has an amicable partner `b`. Amicable means `b = s(a)`, `b ≠ a` and `s(b) = a`, where `s(n)` is the sum of the proper divisors of `n`.

```python
def amicable_numbers_sum(limit):
    """Return the sum of all amicable numbers from 1 to limit (inclusive)."""
    if not isinstance(limit, int):
        raise TypeError("Input must be an integer.")
    if limit < 1:
        return 0

    # Sieve: sum of proper divisors for every number up to limit
    div_sum = [0] * (limit + 1)
    for i in range(1, limit // 2 + 1):
        for j in range(2 * i, limit + 1, i):
            div_sum[j] += i

    def proper_divisor_sum(n):
        if n <= limit:
            return div_sum[n]
        if n < 2:
            return 0
        total = 1
        d = 2
        while d * d <= n:
            if n % d == 0:
                total += d
                other = n // d
                if other != d:
                    total += other
            d += 1
        return total

    total = 0
    for a in range(2, limit + 1):
        b = div_sum[a]
        if b != a and b > 0 and proper_divisor_sum(b) == a:
            total += a
    return total


if __name__ == "__main__":
    assert amicable_numbers_sum(999) == 504
    assert amicable_numbers_sum(9999) == 31626
    assert amicable_numbers_sum(99) == 0
    print("All tests passed.")
