def replace_spaces(text):
    """Swap spaces and underscores: each ' ' becomes '_' and each '_' becomes ' '."""
    result = []
    for ch in text:
        if ch == ' ':
            result.append('_')
        elif ch == '_':
            result.append(' ')
        else:
            result.append(ch)
    return ''.join(result)


