def sequential_search(dlist, item):
    """
    Perform a sequential (linear) search for item in dlist.

    Returns a tuple (found, index), where found is True if item is in dlist,
    and index is the position of the first occurrence (or -1 if not found).
    """
    for index, value in enumerate(dlist):
        if value == item:
            return (True, index)
    return (False, -1)


