    assert sequential_search([9, 10, 17, 19, 22, 39, 48, 56], 48) == (True, 6)
    assert sequential_search([1, 2, 3], 4) == (False, -1)
    assert sequential_search([], 1) == (False, -1)
    print("All tests passed.")
```

